class MapClimateStaticDataTester {
public:
    static MapClimateStaticDataKey make_key (u16 raw) {
        return MapClimateStaticDataKey::from_raw(raw);
    }
};

void test_set_items_updates_count () {
    static MapClimateStaticDataStruct items[3];
    items[0].mvt_cost = 1;  items[0].defense_mod = 10;
    items[1].mvt_cost = 2;  items[1].defense_mod = 20;
    items[2].mvt_cost = 3;  items[2].defense_mod = 30;
    MapClimateStaticData data;
    data.set_items(items, 3);
    note_result(data.get_item_count() == 3, "set_items updates item count");
    summarize_test_results();
}

void test_get_item_returns_expected_struct_by_key () {
    static MapClimateStaticDataStruct items[4];
    items[0].mvt_cost = 7;   items[0].defense_mod = 70;
    items[1].mvt_cost = 8;   items[1].defense_mod = 80;
    items[2].mvt_cost = 9;   items[2].defense_mod = 90;
    items[3].mvt_cost = 10;  items[3].defense_mod = 100;
    MapClimateStaticData data;
    data.set_items(items, 4);

    MapClimateStaticDataKey key = MapClimateStaticDataTester::make_key(2);
    const MapClimateStaticDataStruct& item = data.get_item(key);

    note_result(item.mvt_cost == 9, "get_item returns expected member1");
    note_result(item.defense_mod == 90, "get_item returns expected member2");
    summarize_test_results();
}

void test_get_item_returns_reference_to_backing_array () {
    static MapClimateStaticDataStruct items[2];
    items[0].mvt_cost = 11;  items[0].defense_mod = 110;
    items[1].mvt_cost = 12;  items[1].defense_mod = 120;
    MapClimateStaticData data;
    data.set_items(items, 2);

    MapClimateStaticDataKey key = MapClimateStaticDataTester::make_key(1);
    const MapClimateStaticDataStruct& item = data.get_item(key);

    note_result(&item == &items[1], "get_item returns reference into backing array");
    summarize_test_results();
}

void test_set_items_can_replace_array_and_count () {
    static MapClimateStaticDataStruct items_a[2];
    items_a[0].mvt_cost = 21; items_a[0].defense_mod = 210;
    items_a[1].mvt_cost = 22; items_a[1].defense_mod = 220;
    static MapClimateStaticDataStruct items_b[5];
    items_b[0].mvt_cost = 31; items_b[0].defense_mod = 131;
    items_b[1].mvt_cost = 32; items_b[1].defense_mod = 132;
    items_b[2].mvt_cost = 33; items_b[2].defense_mod = 133;
    items_b[3].mvt_cost = 34; items_b[3].defense_mod = 134;
    items_b[4].mvt_cost = 35; items_b[4].defense_mod = 135;

    MapClimateStaticData data;
    data.set_items(items_a, 2);
    note_result(data.get_item_count() == 2, "initial array count set");

    data.set_items(items_b, 5);
    note_result(data.get_item_count() == 5, "replacement array count set");
    MapClimateStaticDataKey key = MapClimateStaticDataTester::make_key(4);
    const MapClimateStaticDataStruct& item = data.get_item(key);
    note_result(item.mvt_cost == 35, "replacement array item accessible");
    summarize_test_results();
}

void test_zero_count_is_allowed () {
    static MapClimateStaticDataStruct items[1];
    items[0].mvt_cost = 41; items[0].defense_mod = 141;
    MapClimateStaticData data;
    data.set_items(items, 0);
    note_result(data.get_item_count() == 0, "zero item count can be stored");
    summarize_test_results();
}

void test_take_ownership_copies_backing_array () {
    MapClimateStaticDataStruct* items = new MapClimateStaticDataStruct[2];
    items[0].mvt_cost = 51; items[0].defense_mod = 151;
    items[1].mvt_cost = 52; items[1].defense_mod = 152;
    MapClimateStaticData data;
    data.set_items(items, 2);
    MapClimateStaticDataKey key = MapClimateStaticDataTester::make_key(1);
    const void* src_ref = &data.get_item(key);
    data.take_ownership();
    const MapClimateStaticDataStruct& item = data.get_item(key);

    note_result(&item != src_ref, "take_ownership uses a distinct buffer");
    note_result(item.mvt_cost == 52, "take_ownership preserves member1");
    note_result(item.defense_mod == 152, "take_ownership preserves member2");
    data.release_items();
    summarize_test_results();
}

